import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { createAndLinkProductOptionsToProductWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await createAndLinkProductOptionsToProductWorkflow(req
      .scope)
    .run({
      input: {
        product_id: "prod_123"
        add: [
          // Add existing option by ID
          "opt_456",
          // Create new option
          {
            title: "Size",
            values: ["S", "M", "L", "XL"]
          },
          // Add existing option with specific values
          {
            id: "opt_123"
            value_ids: ["optval_1", "optval_2"]
          }
        ],
        remove: ["opt_321"],
        update: [{
          product_option_id: "opt_123",
          add: [
            // add existing value
            "optval_3",
            // add new value
            { value: "optval_4" }
          ],
          remove: ["optval_1"]
        }]
      }
    })

  res.send(result)
}

